import {compressMarketPhoto} from './market-images.mjs?v=20261025-fotos';
export async function openMarketEditor(item,onSaved){
 const previous=document.querySelector('[data-market-editor]');if(previous?.open)return;
 previous?.remove();const dialog=document.createElement('dialog');dialog.className='market-edit-dialog';dialog.dataset.marketEditor='';dialog.setAttribute('aria-labelledby','market-editor-title');
 dialog.innerHTML='<button type="button" data-editor-close>Cancelar y cerrar ✕</button><h2 id="market-editor-title">Editar anuncio</h2><p>Los cambios se aplican al guardar. El anuncio conserva su estado actual.</p><form class="club-form"><fieldset><label>Nombre de la pieza<input name="title" required minlength="4" maxlength="100"></label><label>Temática<select name="category"><option>Motor</option><option>Llantas y neumáticos</option><option>Interior</option><option>Exterior</option><option>Otros</option></select></label><label>Descripción<textarea name="description" rows="5" required minlength="20" maxlength="2500"></textarea></label><label>Precio (€)<input name="price" type="number" required min="0" max="100000" step="0.01"></label><label>Estado de la pieza<input name="condition" required minlength="2" maxlength="50"></label><label>Compatibilidad<input name="compatibility" required minlength="2" maxlength="150"></label><label>Localidad<input name="location" required minlength="2" maxlength="100"></label><label>Vendedor<input name="seller" required minlength="2" maxlength="80"></label><label>Tipo de contacto<select name="contact_type"><option value="email">Correo electrónico</option><option value="phone">Teléfono</option><option value="instagram">Instagram</option></select></label><label>Contacto<input name="contact_value" required minlength="3" maxlength="150"></label><h3>Fotos conservadas</h3><div class="market-editor-photos" data-kept-photos></div><label>Añadir fotografías<input name="photos" type="file" multiple accept="image/jpeg,image/png,image/webp"></label><div class="photo-previews" data-editor-previews></div><p data-editor-count aria-live="polite"></p><button class="button" type="submit">Guardar cambios</button></fieldset><p data-editor-status role="status" aria-live="polite"></p></form>';
 document.body.append(dialog);const form=dialog.querySelector('form'),status=dialog.querySelector('[data-editor-status]'),close=dialog.querySelector('[data-editor-close]');let busy=false,urls=[],keep=item.photoIds.map((id,i)=>({id,url:item.images[i]}));
 for(const key of ['title','category','description','price','condition','compatibility','location','seller'])form.elements[key].value=item[key];form.elements.contact_type.value=item.contactType;form.elements.contact_value.value=item.contactValue;
 const count=()=>{dialog.querySelector('[data-editor-count]').textContent=(keep.length+form.elements.photos.files.length)+' / 10 fotos. Debe quedar al menos una.';};
 function paintKept(){const grid=dialog.querySelector('[data-kept-photos]');grid.replaceChildren();keep.forEach((photo,i)=>{const card=document.createElement('div'),img=document.createElement('img'),remove=document.createElement('button'),cover=document.createElement('button');img.src=photo.url;img.alt='Foto conservada '+(i+1);remove.type=cover.type='button';remove.textContent='Quitar foto '+(i+1);remove.onclick=()=>{keep=keep.filter(p=>p.id!==photo.id);paintKept();};cover.textContent=i===0?'Portada':'Usar como portada';cover.disabled=i===0;cover.onclick=()=>{keep=[photo,...keep.filter(p=>p.id!==photo.id)];paintKept();};card.append(img,cover,remove);grid.append(card);});count();}
 form.elements.photos.onchange=()=>{urls.forEach(URL.revokeObjectURL);urls=[];const grid=dialog.querySelector('[data-editor-previews]');grid.replaceChildren();for(const file of [...form.elements.photos.files].slice(0,10)){const img=document.createElement('img');img.src=URL.createObjectURL(file);urls.push(img.src);img.alt='Nueva foto de la pieza';grid.append(img);}count();};
 close.onclick=()=>{if(!busy)dialog.close();};dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();});dialog.addEventListener('close',()=>{urls.forEach(URL.revokeObjectURL);dialog.remove();});
 form.onsubmit=async event=>{event.preventDefault();if(busy)return;const files=[...form.elements.photos.files];if(keep.length+files.length<1||keep.length+files.length>10){status.textContent='El anuncio debe tener entre 1 y 10 fotos.';return;}
  const data=new FormData(form);data.delete('photos');data.set('keepPhotos',JSON.stringify(keep.map(p=>p.id)));data.set('version',item.editVersion||'');busy=true;close.disabled=true;form.querySelector('fieldset').disabled=true;
  try{for(const [i,file]of files.entries()){status.textContent='Preparando foto '+(i+1)+' de '+files.length+'…';data.append('photos',await compressMarketPhoto(file),'pieza.jpg');}status.textContent='Guardando cambios…';const response=await fetch('/api/admin/listings/'+encodeURIComponent(item.id)+'/edit',{method:'POST',body:data});const result=await response.json();if(!response.ok)throw Error(result.error||'No se pudieron guardar los cambios.');busy=false;dialog.close();await onSaved();window.dispatchEvent(new Event('club-session-change'));}catch(error){status.textContent=error.message;}finally{busy=false;close.disabled=false;form.querySelector('fieldset').disabled=false;}
 };
 paintKept();dialog.showModal();form.elements.title.focus();
}
